// ==========================================
// MÓDULO 1: CARROSSEL DE IMAGENS AUTOMÁTICO
// ==========================================
function iniciarCarrossel() {
    document.querySelectorAll(".auto-slide").forEach(elementoCarrossel => {
        let imagens = elementoCarrossel.querySelectorAll(".slide-item");
        if (imagens.length <= 1) return;

        let indiceAtual = 0;
        setInterval(() => {
            indiceAtual = (indiceAtual + 1) % imagens.length;
            elementoCarrossel.style.transform = `translateX(-${100 * indiceAtual}%)`;
        }, 3500);
    });
}

// ==========================================
// MÓDULO 2: RELÓGIO DE GUERRA TÁTICO
// ==========================================
function iniciarRelogio() {
    let elementoHoras = document.getElementById("warHours");
    let elementoMinutos = document.getElementById("warMinutes");
    let elementoSegundos = document.getElementById("warSeconds");
    let elementoData = document.getElementById("warClockDate");

    if (!(elementoHoras && elementoMinutos && elementoSegundos && elementoData)) return;

    let memoriaHora = "", memoriaMinuto = "", memoriaSegundo = "";
    const meses = ["JAN", "FEV", "MAR", "ABR", "MAI", "JUN", "JUL", "AGO", "SET", "OUT", "NOV", "DEZ"];

    const framesAnimacao = [
        { transform: "perspective(200px) rotateX(0deg)", opacity: 1 },
        { transform: "perspective(200px) rotateX(90deg)", opacity: .5, offset: .5 },
        { transform: "perspective(200px) rotateX(0deg)", opacity: 1 }
    ];
    const opcoesAnimacao = { duration: 300, easing: "ease-in-out" };

    const atualizarTempo = () => {
        let agora = new Date();
        let h = String(agora.getHours()).padStart(2, "0");
        let m = String(agora.getMinutes()).padStart(2, "0");
        let s = String(agora.getSeconds()).padStart(2, "0");

        if (h !== memoriaHora) {
            elementoHoras.textContent = h;
            elementoHoras.animate(framesAnimacao, opcoesAnimacao);
            memoriaHora = h;
        }
        if (m !== memoriaMinuto) {
            elementoMinutos.textContent = m;
            elementoMinutos.animate(framesAnimacao, opcoesAnimacao);
            memoriaMinuto = m;
        }
        if (s !== memoriaSegundo) {
            elementoSegundos.textContent = s;
            elementoSegundos.animate(framesAnimacao, opcoesAnimacao);
            memoriaSegundo = s;
        }

        let dia = String(agora.getDate()).padStart(2, "0");
        elementoData.textContent = `${dia} ${meses[agora.getMonth()]} ${agora.getFullYear()}`;
    };

    atualizarTempo();
    setInterval(atualizarTempo, 1000);
}

// ==========================================
// MÓDULO 3: AUTENTICAÇÃO SEGURA (LOGIN / LOGOUT)
// ==========================================
function iniciarLogin(prefixoUrl) {
    let modalLogin = document.getElementById("loginModal");
    if (!modalLogin) return;

    let btnAbreModal = document.querySelector(".btn-login");
    let textoBotaoMenu = document.getElementById("navLoginText");
    let btnFechaModal = document.getElementById("closeModal");
    let formularioLogin = document.getElementById("loginForm");

    let inputEmail = document.getElementById("userEmail");
    let inputSenha = document.getElementById("userPassword");
    let btnAutenticar = document.getElementById("btnSubmitLogin");

    let btnRadar = document.getElementById("btnRadar");
    let iconeRadar = document.getElementById("radarIcon");
    let radarAtivo = false;

    const exibirBanner = (mensagem, icone = "WT - Artes/UI-UX icons/Soldier-salute.webp") => {
        let banner = document.getElementById("customBanner");
        if (banner) {
            document.getElementById("customBannerText").textContent = mensagem;
            document.getElementById("bannerIcon").innerHTML = `<img src="${prefixoUrl}${icone}" style="width:24px;height:auto;object-fit:contain;">`;
            banner.classList.add("show");
            setTimeout(() => banner.classList.remove("show"), 4000);
        }
    };

    window.atualizarControlesInterface = function (isAuth, perfilUsuario) {
        const autenticado = isAuth === true || isAuth === "true";
        const ehAdmin = autenticado && (perfilUsuario || "").toLowerCase() === "admin";

        const botaoMenuRef = document.querySelector(".nav-item:not(.admin-controls)");
        const displayNav = botaoMenuRef ? window.getComputedStyle(botaoMenuRef).display : "flex";

        document.querySelectorAll(".admin-controls").forEach(el => {
            el.style.display = ehAdmin ? displayNav : "none";
        });

        // Atualiza a exibição da placa de nação favorita no topo
        const placaNacao = document.getElementById("userNationBadgeContainer");
        if (placaNacao) {
            placaNacao.style.display = autenticado ? "flex" : "none";
            if (autenticado) {
                renderizarPlacaNacaoTopo(localStorage.getItem("userNation") || "USA", prefixoUrl);
            }
        }
    };

    const validarInputs = () => {
        let emailValido = inputEmail.value.includes("@") && inputEmail.value.includes(".");
        let senhaValida = inputSenha.value.length > 0;
        btnAutenticar.disabled = !(emailValido && senhaValida);
        btnAutenticar.classList.toggle("valido", emailValido && senhaValida);
    };

    if (btnAbreModal) {
        btnAbreModal.addEventListener("click", async (evento) => {
            evento.preventDefault();

            if (localStorage.getItem("isAuth") === "true") {
                try {
                    await fetch(`${prefixoUrl}php/api/logout.php`);

                    localStorage.removeItem("isAuth");
                    localStorage.removeItem("userRole");
                    localStorage.removeItem("userNickname");
                    localStorage.removeItem("userNation");
                    localStorage.removeItem("userName");

                    if (textoBotaoMenu) textoBotaoMenu.textContent = "ENTRAR";
                    exibirBanner("DESCONECTADO.", "WT - Artes/UI-UX icons/Soldier-salute.webp");
                    atualizarControlesInterface(false, "visitante");

                    setTimeout(() => window.location.reload(), 1500);
                } catch (err) {
                    console.error("Falha ao encerrar a sessão no servidor:", err);
                    exibirBanner("Erro ao desconectar da Base Central.");
                }
            } else {
                modalLogin.classList.add("ativo");
            }
        });
    }

    if (btnFechaModal) btnFechaModal.addEventListener("click", () => modalLogin.classList.remove("ativo"));

    if (btnRadar) {
        btnRadar.addEventListener("click", () => {
            if (!radarAtivo && inputSenha.value !== "") {
                if (inputSenha.type === "password") {
                    radarAtivo = true;
                    let senhaOriginal = inputSenha.value;
                    inputSenha.type = "text";
                    iconeRadar.src = `${prefixoUrl}WT - Artes/UI-UX icons/Radar-ver.webp`;
                    inputSenha.disabled = true;

                    let passos = 0;
                    let embaralhar = setInterval(() => {
                        inputSenha.value = senhaOriginal.split("").map(() => {
                            let caracteres = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%&*";
                            return caracteres[Math.floor(43 * Math.random())];
                        }).join("");
                        passos++;

                        if (passos > 12) {
                            clearInterval(embaralhar);
                            inputSenha.value = senhaOriginal;
                            inputSenha.disabled = false;
                            radarAtivo = false;
                        }
                    }, 40);
                } else {
                    inputSenha.type = "password";
                    iconeRadar.src = `${prefixoUrl}WT - Artes/UI-UX icons/Radar-ocultar.webp`;
                }
            }
        });
    }

    inputEmail.addEventListener("input", validarInputs);
    inputSenha.addEventListener("input", validarInputs);

    formularioLogin.addEventListener("submit", async (evento) => {
        evento.preventDefault();

        const feedback = document.getElementById("loginFeedback");
        if (feedback) feedback.style.display = "none";

        btnAutenticar.disabled = true;
        btnAutenticar.innerHTML = `<img src="${prefixoUrl}WT - Artes/UI-UX icons/Loading-icon.webp" alt="" style="width:24px;animation:spin 1s linear infinite;"> AUTENTICANDO...`;
        btnAutenticar.style.backgroundColor = "#F2B400";

        try {
            let formData = new FormData();
            formData.append("email", inputEmail.value);
            formData.append("senha", inputSenha.value);

            const resposta = await fetch(`${prefixoUrl}php/api/auth.php`, {
                method: "POST",
                body: formData
            });

            const textoResposta = await resposta.text();
            let json;
            try {
                json = JSON.parse(textoResposta);
            } catch (e) {
                console.error("Retorno não-JSON do PHP:", textoResposta);
                throw new Error("Erro no servidor PHP. Verifique o console.");
            }

            if (resposta.ok && json.status === "success") {
                localStorage.setItem("isAuth", "true");
                localStorage.setItem("userRole", json.perfil);
                localStorage.setItem("userNickname", json.nickname);
                localStorage.setItem("userNation", json.nacao_favorita || "USA");

                document.getElementById("loginModal").classList.remove("ativo");
                if (textoBotaoMenu) textoBotaoMenu.textContent = "SAIR";

                exibirBanner(`BEM-VINDO, ${json.nickname.toUpperCase()}`);
                atualizarControlesInterface(true, json.perfil);

                setTimeout(() => window.location.reload(), 1200);
            } else {
                btnAutenticar.innerHTML = "ACESSO NEGADO";
                btnAutenticar.style.backgroundColor = "#e81000";

                if (feedback) {
                    feedback.textContent = json.message;
                    feedback.style.display = "block";
                }

                setTimeout(() => {
                    btnAutenticar.innerHTML = "AUTENTICAR";
                    btnAutenticar.style.backgroundColor = "";
                    btnAutenticar.disabled = false;
                }, 2000);
            }
        } catch (erro) {
            console.error("Erro na requisição:", erro);
            btnAutenticar.innerHTML = "FALHA DE CONEXÃO";
            btnAutenticar.style.backgroundColor = "#e81000";

            if (feedback) {
                feedback.textContent = erro.message;
                feedback.style.display = "block";
            }

            setTimeout(() => {
                btnAutenticar.innerHTML = "AUTENTICAR";
                btnAutenticar.style.backgroundColor = "";
                btnAutenticar.disabled = false;
            }, 2000);
        }
    });

    const linkParaReg = document.getElementById("linkIrParaRegistro");
    const linkParaLog = document.getElementById("linkIrParaLogin");
    const modalRegisto = document.getElementById("registerModal");

    if (linkParaReg && modalLogin && modalRegisto) {
        linkParaReg.addEventListener("click", (e) => {
            e.preventDefault();
            modalLogin.classList.remove("ativo");
            modalRegisto.classList.add("ativo");
        });
    }

    if (linkParaLog && modalLogin && modalRegisto) {
        linkParaLog.addEventListener("click", (e) => {
            e.preventDefault();
            modalRegisto.classList.remove("ativo");
            modalLogin.classList.add("ativo");
        });
    }

    (function verificarSessaoInicial() {
        let isAuth = localStorage.getItem("isAuth") === "true";
        let perfilUsuario = localStorage.getItem("userRole") || "visitante";

        if (isAuth) {
            if (textoBotaoMenu) textoBotaoMenu.textContent = "SAIR";
            atualizarControlesInterface(true, perfilUsuario);
        } else {
            if (textoBotaoMenu) textoBotaoMenu.textContent = "ENTRAR";
            atualizarControlesInterface(false, "visitante");
        }
    })();
}

// ==========================================
// GESTÃO VISUAL DA NAÇÃO FAVORITA (NAVBAR)
// ==========================================
function renderizarPlacaNacaoTopo(siglaNacao, prefixoUrl) {
    const badge = document.getElementById("userNationBadge");
    const cfg = NACOES_CONFIG[siglaNacao] || NACOES_CONFIG.USA;

    if (!badge) return;

    badge.style.borderColor = cfg.corBorda;
    badge.style.boxShadow = `0 0 10px ${cfg.glow}`;
    badge.innerHTML = `
        <div style="display:flex;align-items:center;gap:6px;">
            ${cfg.svg}
            <span style="font-weight:bold;color:#fff;font-size:11px;letter-spacing:1px;">${cfg.sigla}</span>
        </div>
        <span style="font-size:9px;color:#aaa;text-transform:uppercase;">${cfg.nome}</span>
        <span style="font-size:8px;color:#F2B400;margin-left:2px;">▼</span>
    `;
}

function iniciarSeletorNacao(prefixoUrl) {
    const badge = document.getElementById("userNationBadge");
    const dropdown = document.getElementById("userNationDropdown");

    if (!badge || !dropdown) return;

    badge.addEventListener("click", (e) => {
        e.stopPropagation();
        dropdown.style.display = dropdown.style.display === "block" ? "none" : "block";
    });

    document.addEventListener("click", () => {
        dropdown.style.display = "none";
    });

    dropdown.querySelectorAll(".nation-opt").forEach(opt => {
        opt.addEventListener("click", async (e) => {
            e.stopPropagation();
            const nacaoEscolhida = opt.getAttribute("data-nation");

            try {
                let formData = new FormData();
                formData.append("acao", "salvar_nacao");
                formData.append("nacao", nacaoEscolhida);

                const res = await fetch(`${prefixoUrl}php/api/usuarios.php`, {
                    method: "POST",
                    body: formData
                });
                const json = await res.json();

                if (res.ok && json.status === "success") {
                    localStorage.setItem("userNation", nacaoEscolhida);
                    renderizarPlacaNacaoTopo(nacaoEscolhida, prefixoUrl);
                    dropdown.style.display = "none";
                }
            } catch (err) {
                console.error("Falha ao salvar nação:", err);
            }
        });
    });
}

// ==========================================
// MÓDULO 4: REGISTO DE NOVOS SOLDADOS (ALISTAMENTO)
// ==========================================
function iniciarRegistro(prefixoUrl) {
    let modalRegisto = document.getElementById("registerModal");
    let btnFechaRegisto = document.getElementById("closeRegisterModal");
    let formRegisto = document.getElementById("registerForm");

    let inputNome = document.getElementById("regNome");
    let inputSobrenome = document.getElementById("regSobrenome");
    let inputNickname = document.getElementById("regNickname");
    let inputEmail = document.getElementById("regEmail");
    let inputSenha = document.getElementById("regSenha");
    let inputConfirmar = document.getElementById("regConfirmar");

    let avisoSenha = document.getElementById("regErroSenha");
    let regFeedback = document.getElementById("registerFeedback");
    let btnSubmit = document.getElementById("btnSubmitRegister");

    let btnRadarReg = document.getElementById("btnRadarReg");
    let iconeRadarReg = document.getElementById("radarIconReg");
    let inputTelefone = document.getElementById("regTelefone");

    let iti;
    if (window.intlTelInput && inputTelefone) {
        iti = window.intlTelInput(inputTelefone, {
            initialCountry: "br",
            utilsScript: "https://cdn.jsdelivr.net/npm/intl-tel-input@23.0.10/build/js/utils.js"
        });
    }

    if (btnRadarReg) {
        btnRadarReg.addEventListener("click", () => {
            if (inputSenha.type === "password") {
                inputSenha.type = "text";
                iconeRadarReg.src = `${prefixoUrl}WT - Artes/UI-UX icons/Radar-ver.webp`;
            } else {
                inputSenha.type = "password";
                iconeRadarReg.src = `${prefixoUrl}WT - Artes/UI-UX icons/Radar-ocultar.webp`;
            }
        });
    }

    if (!modalRegisto || !formRegisto) return;

    const resetarAvisos = () => {
        if (avisoSenha) avisoSenha.style.display = "none";
        if (regFeedback) regFeedback.style.display = "none";
    };

    const validarBotaoVisualmente = () => {
        let preenchido =
            inputNome.value.trim().length > 0 &&
            inputSobrenome.value.trim().length > 0 &&
            inputNickname.value.trim().length > 0 &&
            inputEmail.value.includes("@") &&
            inputSenha.value.length > 0 &&
            inputConfirmar.value.length > 0;

        btnSubmit.disabled = !preenchido;
        btnSubmit.classList.toggle("valido", preenchido);
    };

    [inputNome, inputSobrenome, inputNickname, inputEmail, inputSenha, inputConfirmar].forEach(input => {
        input.addEventListener("input", () => {
            resetarAvisos();
            validarBotaoVisualmente();
        });
    });

    if (btnFechaRegisto) {
        btnFechaRegisto.addEventListener("click", () => {
            modalRegisto.classList.remove("ativo");
            formRegisto.reset();
            resetarAvisos();
            validarBotaoVisualmente();
        });
    }

    formRegisto.addEventListener("submit", async (evento) => {
        evento.preventDefault();
        resetarAvisos();

        if (inputSenha.value !== inputConfirmar.value) {
            avisoSenha.textContent = "AS CHAVES CRIPTOGRÁFICAS NÃO COINCIDEM.";
            avisoSenha.style.display = "block";
            return;
        }

        const valSenha = inputSenha.value;
        if (valSenha.length < 8) {
            avisoSenha.textContent = "A CHAVE DEVE TER NO MÍNIMO 8 CARACTERES.";
            avisoSenha.style.display = "block";
            return;
        }
        if (!/[A-Z]/.test(valSenha) || !/[a-z]/.test(valSenha)) {
            avisoSenha.textContent = "A CHAVE DEVE CONTER LETRAS MAIÚSCULAS E MINÚSCULAS.";
            avisoSenha.style.display = "block";
            return;
        }
        if (!/\d/.test(valSenha)) {
            avisoSenha.textContent = "A CHAVE DEVE CONTER AO MENOS UM NÚMERO (0-9).";
            avisoSenha.style.display = "block";
            return;
        }
        if (!/[\W_]/.test(valSenha)) {
            avisoSenha.textContent = "A CHAVE DEVE CONTER AO MENOS UM SÍMBOLO ESPECIAL (!@#\$%&*...).";
            avisoSenha.style.display = "block";
            return;
        }

        const emailDigitado = inputEmail.value.trim().toLowerCase();
        const partesEmail = emailDigitado.split("@");
        const dominio = partesEmail[1] || "";
        const errosComuns = [
            'gamil.com', 'gmaill.com', 'gmai.com', 'gmail.com.br', 'gmeil.com',
            'hotmial.com', 'hotmai.com', 'outlok.com', 'yaho.com'
        ];

        if (dominio === "wtwiki.com") {
            regFeedback.textContent = "ACESSO NEGADO: O domínio @wtwiki.com é restrito ao Alto Comando.";
            regFeedback.style.display = "block";
            return;
        }

        if (errosComuns.includes(dominio)) {
            regFeedback.textContent = `DOMÍNIO SUSPEITO: Você digitou @${dominio}. Corrija para um provedor válido (ex: @gmail.com).`;
            regFeedback.style.display = "block";
            return;
        }

        btnSubmit.disabled = true;
        btnSubmit.classList.remove("valido");
        let textoOriginal = btnSubmit.innerHTML;
        btnSubmit.innerHTML = `<img src="${prefixoUrl}WT - Artes/UI-UX icons/Loading-icon.webp" alt="" style="width:24px;animation:spin 1s linear infinite;"> PROCESSANDO...`;

        try {
            let formData = new FormData();
            formData.append("nome", inputNome.value);
            formData.append("sobrenome", inputSobrenome.value);
            formData.append("nickname", inputNickname.value);
            formData.append("email", inputEmail.value);
            formData.append("email_contato", document.getElementById("regEmailContato").value);
            formData.append("telefone", iti ? iti.getNumber() : inputTelefone.value);
            formData.append("senha", inputSenha.value);

            const resposta = await fetch(`${prefixoUrl}php/api/register.php`, {
                method: "POST",
                body: formData
            });

            const textoResposta = await resposta.text();
            let json;
            try {
                json = JSON.parse(textoResposta);
            } catch (erroJson) {
                console.error("Resposta Inválida do Servidor (PHP):", textoResposta);
                throw new Error("O servidor retornou um erro interno e não um JSON válido.");
            }

            if (resposta.ok && json.status === "success") {
                btnSubmit.innerHTML = "ALISTAMENTO CONCLUÍDO!";
                btnSubmit.style.backgroundColor = "#4caf50";

                let banner = document.getElementById("customBanner");
                if (banner) {
                    document.getElementById("customBannerText").textContent = "Soldado registrado! Proceda com a autenticação.";
                    banner.classList.add("show");
                    setTimeout(() => banner.classList.remove("show"), 5000);
                }

                setTimeout(() => {
                    modalRegisto.classList.remove("ativo");
                    formRegisto.reset();
                    btnSubmit.innerHTML = textoOriginal;
                    btnSubmit.style.backgroundColor = "";
                    validarBotaoVisualmente();

                    document.getElementById("loginModal").classList.add("ativo");
                }, 2000);

            } else {
                if (regFeedback) {
                    regFeedback.textContent = json.message;
                    regFeedback.style.display = "block";
                }
                btnSubmit.innerHTML = textoOriginal;
                validarBotaoVisualmente();
            }
        } catch (erro) {
            console.error(erro);
            if (regFeedback) {
                regFeedback.textContent = erro.message;
                regFeedback.style.display = "block";
            }
            btnSubmit.innerHTML = textoOriginal;
            validarBotaoVisualmente();
        }
    });
}

// ========================================================
// MÓDULO 4.1: RECUPERAÇÃO E REDEFINIÇÃO DE CHAVE CRIPTOGRÁFICA
// ========================================================
function iniciarRecuperacaoSenha(prefixoUrl) {
    const btnEsqueci = document.getElementById("esqueciSenhaBtn");
    const modalRecover = document.getElementById("recoverModal");
    const closeRecover = document.getElementById("closeRecoverModal");
    const formRecover = document.getElementById("recoverForm");
    const formReset = document.getElementById("resetForm");
    const recoverFeedback = document.getElementById("recoverFeedback");

    if (!modalRecover) return;

    if (btnEsqueci) {
        btnEsqueci.addEventListener("click", (e) => {
            e.preventDefault();
            const modalLogin = document.getElementById("loginModal");
            if (modalLogin) modalLogin.classList.remove("ativo");
            modalRecover.classList.add("ativo");
            if (recoverFeedback) recoverFeedback.style.display = "none";
        });
    }

    if (closeRecover) {
        closeRecover.addEventListener("click", () => modalRecover.classList.remove("ativo"));
    }

    if (formRecover) {
        formRecover.addEventListener("submit", async (e) => {
            e.preventDefault();
            const btnSubmit = document.getElementById("btnSubmitRecover");
            const textoOriginal = btnSubmit.innerHTML;

            btnSubmit.disabled = true;
            btnSubmit.innerHTML = `<img src="${prefixoUrl}WT - Artes/UI-UX icons/Loading-icon.webp" alt="" style="width:20px;height:auto;vertical-align:middle;animation:spin 1s linear infinite;"> LOCALIZANDO...`;
            btnSubmit.style.backgroundColor = "#F2B400";

            try {
                let formData = new FormData();
                formData.append("email", document.getElementById("recoverEmail").value);

                const res = await fetch(`${prefixoUrl}php/api/recover.php`, {
                    method: "POST",
                    body: formData
                });
                const json = await res.json();

                if (recoverFeedback) {
                    recoverFeedback.style.display = "block";
                    recoverFeedback.style.borderLeftColor = json.status === "success" ? "#4caf50" : "var(--rus-vermelho)";
                    recoverFeedback.style.background = json.status === "success" ? "#122a18" : "#2a1212";
                    recoverFeedback.style.color = json.status === "success" ? "#80ff9f" : "#ff8080";
                    recoverFeedback.textContent = json.message;
                }

                if (json.status === "success") {
                    formRecover.style.display = "none";
                    formReset.style.display = "block";
                    if (json.token_teste) {
                        document.getElementById("resetToken").value = json.token_teste;
                    }
                }
            } catch (err) {
                if (recoverFeedback) {
                    recoverFeedback.style.display = "block";
                    recoverFeedback.textContent = "Falha ao contactar a central de recuperação.";
                }
            } finally {
                btnSubmit.innerHTML = textoOriginal;
                btnSubmit.style.backgroundColor = "";
                btnSubmit.disabled = false;
            }
        });
    }

    if (formReset) {
        formReset.addEventListener("submit", async (e) => {
            e.preventDefault();
            const btnSubmit = document.getElementById("btnSubmitReset");
            const textoOriginal = btnSubmit.innerHTML;

            btnSubmit.disabled = true;
            btnSubmit.innerHTML = `<img src="${prefixoUrl}WT - Artes/UI-UX icons/Loading-icon.webp" alt="" style="width:20px;height:auto;vertical-align:middle;animation:spin 1s linear infinite;"> REDEFININDO...`;
            btnSubmit.style.backgroundColor = "#F2B400";

            try {
                let formData = new FormData();
                formData.append("token", document.getElementById("resetToken").value);
                formData.append("nova_senha", document.getElementById("resetSenha").value);

                const res = await fetch(`${prefixoUrl}php/api/reset_password.php`, {
                    method: "POST",
                    body: formData
                });
                const json = await res.json();

                if (recoverFeedback) {
                    recoverFeedback.style.display = "block";
                    recoverFeedback.textContent = json.message;
                }

                if (json.status === "success") {
                    setTimeout(() => {
                        modalRecover.classList.remove("ativo");
                        formReset.reset();
                        formRecover.reset();
                        formRecover.style.display = "block";
                        formReset.style.display = "none";

                        const modalLogin = document.getElementById("loginModal");
                        if (modalLogin) modalLogin.classList.add("ativo");
                    }, 1800);
                }
            } catch (err) {
                if (recoverFeedback) {
                    recoverFeedback.style.display = "block";
                    recoverFeedback.textContent = "Erro ao redefinir a credencial.";
                }
            } finally {
                btnSubmit.innerHTML = textoOriginal;
                btnSubmit.style.backgroundColor = "";
                btnSubmit.disabled = false;
            }
        });
    }
}

// ========================================================
// MÓDULO 4.2: GESTÃO DE TROPAS COM BUSCA E FILTROS
// ========================================================
function iniciarTropas(prefixoUrl) {
    const btnOpen = document.getElementById("btnOpenTropas");
    const modal = document.getElementById("tropasModal");
    const btnClose = document.getElementById("closeTropasModal");
    const tabSoldados = document.getElementById("tabTropasSoldados");
    const tabAuditoria = document.getElementById("tabTropasAuditoria");
    const painelSoldados = document.getElementById("painelSoldados");
    const painelAuditoria = document.getElementById("painelAuditoria");
    const tbody = document.getElementById("listaSoldadosTbody");
    const logsContainer = document.getElementById("listaLogsContainer");
    const feedback = document.getElementById("tropasFeedback");

    // Elementos de Pesquisa e Ordenação
    const inputBusca = document.getElementById("buscaSoldadoInput");
    const selectOrdem = document.getElementById("ordenaSoldadosSelect");
    const selectNacaoFiltro = document.getElementById("filtroNacaoSelect");

    let cacheUsuarios = [];

    if (!modal) return;

    if (tabSoldados && tabAuditoria) {
        tabSoldados.addEventListener("click", () => {
            tabSoldados.style.backgroundColor = "#F2B400";
            tabSoldados.style.color = "#000";
            tabAuditoria.style.backgroundColor = "#333";
            tabAuditoria.style.color = "#fff";
            painelSoldados.style.display = "block";
            painelAuditoria.style.display = "none";
        });

        tabAuditoria.addEventListener("click", () => {
            tabAuditoria.style.backgroundColor = "#F2B400";
            tabAuditoria.style.color = "#000";
            tabSoldados.style.backgroundColor = "#333";
            tabSoldados.style.color = "#fff";
            painelAuditoria.style.display = "block";
            painelSoldados.style.display = "none";
        });
    }

    if (btnClose) {
        btnClose.addEventListener("click", () => modal.classList.remove("ativo"));
    }

    // Renderização com Filtro e Ordenação
    const renderizarTabelaFiltrada = () => {
        let filtrados = [...cacheUsuarios];

        // 1. Busca por Nickname ou E-mail
        const termo = (inputBusca?.value || "").toLowerCase().trim();
        if (termo) {
            filtrados = filtrados.filter(u =>
                (u.nickname || "").toLowerCase().includes(termo) ||
                (u.email || "").toLowerCase().includes(termo)
            );
        }

        // 2. Filtro de Nação
        const nacaoFiltro = selectNacaoFiltro?.value || "TODAS";
        if (nacaoFiltro !== "TODAS") {
            filtrados = filtrados.filter(u => (u.nacao_favorita || "USA") === nacaoFiltro);
        }

        // 3. Ordenação
        const ordem = selectOrdem?.value || "recente";
        if (ordem === "recente") {
            filtrados.sort((a, b) => b.id - a.id);
        } else if (ordem === "antigo") {
            filtrados.sort((a, b) => a.id - b.id);
        } else if (ordem === "az") {
            filtrados.sort((a, b) => a.nickname.localeCompare(b.nickname));
        } else if (ordem === "za") {
            filtrados.sort((a, b) => b.nickname.localeCompare(a.nickname));
        }

        // 4. Injeção no HTML
        tbody.innerHTML = "";
        if (filtrados.length === 0) {
            tbody.innerHTML = `<tr><td colspan="6" style="text-align: center; color: #888; padding: 25px;">Nenhum soldado encontrado nos registros.</td></tr>`;
            return;
        }

        filtrados.forEach(user => {
            const tr = document.createElement("tr");
            tr.style.borderBottom = "1px solid #222";

            const isAtivo = user.status === 'ativo';
            const statusCor = isAtivo ? "#4caf50" : "var(--rus-vermelho)";
            const cfgNacao = NACOES_CONFIG[user.nacao_favorita] || NACOES_CONFIG.USA;

            tr.innerHTML = `
                <td style="padding: 8px; font-weight: bold; color: #fff;">${user.nickname}</td>
                <td style="padding: 8px; color: #aaa;">${user.email}</td>
                <td style="padding: 8px;">
                    <div style="display:inline-flex;align-items:center;gap:6px;padding:3px 6px;border:1px solid ${cfgNacao.corBorda};background:#111;border-radius:3px;">
                        ${cfgNacao.svg}
                        <span style="font-size:10px;font-weight:bold;color:#fff;">${cfgNacao.sigla}</span>
                    </div>
                </td>
                <td style="padding: 8px;">
                    <select class="select-perfil" data-id="${user.id}" style="background: #1a1a1a; color: #fff; border: 1px solid #444; padding: 4px; font-size: 11px;">
                        <option value="visitante" ${user.perfil === 'visitante' ? 'selected' : ''}>Soldado (Visitante)</option>
                        <option value="admin" ${user.perfil === 'admin' ? 'selected' : ''}>Comandante (Admin)</option>
                    </select>
                </td>
                <td style="padding: 8px; font-weight: bold; color: ${statusCor};">${user.status.toUpperCase()}</td>
                <td style="padding: 8px; text-align: center;">
                    <button class="btn-toggle-status" data-id="${user.id}" style="background: ${isAtivo ? 'var(--rus-vermelho)' : '#4caf50'}; color: #fff; border: none; padding: 4px 8px; font-size: 10px; cursor: pointer; border-radius: 2px;">
                        ${isAtivo ? 'SUSPENDER' : 'REATIVAR'}
                    </button>
                </td>
            `;
            tbody.appendChild(tr);
        });

        vincularAcoesTabela();
    };

    if (inputBusca) inputBusca.addEventListener("input", renderizarTabelaFiltrada);
    if (selectOrdem) selectOrdem.addEventListener("change", renderizarTabelaFiltrada);
    if (selectNacaoFiltro) selectNacaoFiltro.addEventListener("change", renderizarTabelaFiltrada);

    const carregarDadosTropas = async () => {
        try {
            const res = await fetch(`${prefixoUrl}php/api/usuarios.php`);
            const json = await res.json();

            if (!res.ok || json.status !== "success") {
                if (feedback) {
                    feedback.style.display = "block";
                    feedback.textContent = json.message || "Erro ao consultar efetivo.";
                }
                return;
            }

            cacheUsuarios = json.usuarios;
            renderizarTabelaFiltrada();

            // Renderiza Livro de Registros (Logs)
            logsContainer.innerHTML = "";
            if (json.logs.length === 0) {
                logsContainer.innerHTML = "<div style='text-align: center; color: #777; padding: 20px;'>Nenhum registro tático arquivado.</div>";
            } else {
                json.logs.forEach(log => {
                    const item = document.createElement("div");
                    item.style.padding = "8px 12px";
                    item.style.background = "#181818";
                    item.style.borderLeft = "3px solid #F2B400";
                    item.style.fontSize = "11px";
                    item.innerHTML = `
                        <div style="display:flex; justify-content:space-between; margin-bottom: 3px;">
                            <strong style="color:#F2B400;">${log.acao}</strong>
                            <span style="color:#777;">${log.data_hora}</span>
                        </div>
                        <div style="color:#ccc;">
                            Comandante <strong style="color:#fff;">${log.admin_nickname}</strong> operou em <strong style="color:#fff;">${log.alvo_nickname}</strong>: ${log.detalhes}
                        </div>
                    `;
                    logsContainer.appendChild(item);
                });
            }

        } catch (err) {
            console.error(err);
            if (feedback) {
                feedback.style.display = "block";
                feedback.textContent = "Falha ao sincronizar dados com o servidor.";
            }
        }
    };

    const vincularAcoesTabela = () => {
        document.querySelectorAll(".select-perfil").forEach(select => {
            select.addEventListener("change", async (e) => {
                const id = e.target.getAttribute("data-id");
                const novoPerfil = e.target.value;

                let formData = new FormData();
                formData.append("acao", "mudar_perfil");
                formData.append("usuario_id", id);
                formData.append("novo_perfil", novoPerfil);

                const res = await fetch(`${prefixoUrl}php/api/usuarios.php`, { method: "POST", body: formData });
                const json = await res.json();

                feedback.style.display = "block";
                feedback.style.borderLeft = json.status === "success" ? "4px solid #4caf50" : "4px solid var(--rus-vermelho)";
                feedback.style.background = json.status === "success" ? "#122a18" : "#2a1212";
                feedback.style.color = json.status === "success" ? "#80ff9f" : "#ff8080";
                feedback.textContent = json.message;

                carregarDadosTropas();
            });
        });

        document.querySelectorAll(".btn-toggle-status").forEach(btn => {
            btn.addEventListener("click", async (e) => {
                const id = e.target.getAttribute("data-id");

                let formData = new FormData();
                formData.append("acao", "mudar_status");
                formData.append("usuario_id", id);

                const res = await fetch(`${prefixoUrl}php/api/usuarios.php`, { method: "POST", body: formData });
                const json = await res.json();

                feedback.style.display = "block";
                feedback.style.borderLeft = json.status === "success" ? "4px solid #4caf50" : "4px solid var(--rus-vermelho)";
                feedback.style.background = json.status === "success" ? "#122a18" : "#2a1212";
                feedback.style.color = json.status === "success" ? "#80ff9f" : "#ff8080";
                feedback.textContent = json.message;

                carregarDadosTropas();
            });
        });
    };

    if (btnOpen) {
        btnOpen.addEventListener("click", (e) => {
            e.preventDefault();
            modal.classList.add("ativo");
            if (feedback) feedback.style.display = "none";
            carregarDadosTropas();
        });
    }
}

// ==========================================
// MÓDULO 5: ROLAGEM SUAVE (Scroll to Top)
// ==========================================
function iniciarScrollSuave(prefixoUrl) {
    let htmlBotaoTopo = `<button id="btnVoltarTopo" title="Voltar ao Topo"><img src="${prefixoUrl}WT - Artes/UI-UX icons/Seta_cima-icon.webp" alt="" aria-hidden="true" class="icone-topo"><span class="texto-topo">VOLTAR AO TOPO</span></button>`;
    document.body.insertAdjacentHTML("beforeend", htmlBotaoTopo);

    let btnVoltarTopo = document.getElementById("btnVoltarTopo");
    if (btnVoltarTopo) {
        window.addEventListener("scroll", () => {
            if (window.scrollY > 300) {
                btnVoltarTopo.classList.add("visivel");
            } else {
                btnVoltarTopo.classList.remove("visivel");
            }
        });

        btnVoltarTopo.addEventListener("click", () => {
            document.body.scrollIntoView({ behavior: "smooth", block: "start" });
        });

        document.querySelectorAll('a[href^="#"]').forEach(ancora => {
            ancora.addEventListener("click", function (evento) {
                let destino = this.getAttribute("href");
                if (destino !== "#") {
                    let elementoDestino = document.querySelector(destino);
                    if (elementoDestino) {
                        evento.preventDefault();
                        elementoDestino.scrollIntoView({ behavior: "smooth", block: "start" });
                    }
                }
            });
        });
    }
}

// ==========================================
// MÓDULO 6: MOTOR DE BUSCA INTERNA (MYSQL INTEGRADO)
// ==========================================
function iniciarBusca(prefixoUrl) {
    let esperaInjecao = setInterval(() => {
        let inputBusca = document.getElementById("searchInput");
        let caixaSugestoes = document.getElementById("searchSuggestions");

        if (inputBusca && caixaSugestoes) {
            clearInterval(esperaInjecao);

            let indiceSelecionado = -1;
            let timeoutBusca = null;

            function destacarSugestao(itens) {
                itens.forEach(item => item.classList.remove("ativo"));
                if (indiceSelecionado > -1) {
                    itens[indiceSelecionado].classList.add("ativo");
                    inputBusca.value = itens[indiceSelecionado].querySelector("span").textContent;
                }
            }

            inputBusca.addEventListener("input", () => {
                clearTimeout(timeoutBusca);
                
                let termoBusca = inputBusca.value.trim();
                
                if (termoBusca.length < 2) {
                    caixaSugestoes.innerHTML = "";
                    caixaSugestoes.style.display = "none";
                    indiceSelecionado = -1;
                    return;
                }

                // Dispara a busca no banco de dados via API
                timeoutBusca = setTimeout(async () => {
                    try {
                        const res = await fetch(`${prefixoUrl}php/api/busca_veiculos.php?q=${encodeURIComponent(termoBusca)}`);
                        const json = await res.json();

                        caixaSugestoes.innerHTML = "";
                        indiceSelecionado = -1;

                        if (json.status === "success" && json.resultados.length > 0) {
                            caixaSugestoes.style.display = "block";
                            json.resultados.forEach(tanque => {
                                let li = document.createElement("li");
                                // Atualizado para usar url_pagina e caminho_imagem da sua tabela 'tanques'
                                li.innerHTML = `
                                    <a href="${prefixoUrl}ficha.html?id=${tanque.id}" class="suggestion-link">
                                        <img src="${prefixoUrl}${tanque.caminho_imagem}" alt="" aria-hidden="true" class="suggestion-icon">
                                        <span>${tanque.nome} <small style="color:#F2B400; font-size:9px; margin-left:5px;">(${tanque.nacao})</small></span>
                                    </a>
                                `;
                                li.addEventListener("click", () => {
                                    window.location.href = `${prefixoUrl}${tanque.url_pagina}`;
                                });
                                caixaSugestoes.appendChild(li);
                            });
                        } else {
                            caixaSugestoes.style.display = "none";
                        }
                    } catch (error) {
                        console.error("Falha ao comunicar com o radar do servidor:", error);
                    }
                }, 300);
            });

            inputBusca.addEventListener("keydown", evento => {
                let listaSugestoes = caixaSugestoes.querySelectorAll("li");
                if (listaSugestoes.length !== 0) {
                    if (evento.key === "ArrowDown") {
                        indiceSelecionado++;
                        if (indiceSelecionado >= listaSugestoes.length) indiceSelecionado = -1;
                        destacarSugestao(listaSugestoes);
                    } else if (evento.key === "ArrowUp") {
                        indiceSelecionado--;
                        if (indiceSelecionado < 0) indiceSelecionado = listaSugestoes.length - 1;
                        destacarSugestao(listaSugestoes);
                    } else if (evento.key === "Enter") {
                        evento.preventDefault();
                        if (indiceSelecionado > -1) {
                            listaSugestoes[indiceSelecionado].click();
                        }
                    }
                }
            });

            document.addEventListener("click", evento => {
                if (!inputBusca.contains(evento.target) && !caixaSugestoes.contains(evento.target)) {
                    caixaSugestoes.style.display = "none";
                }
            });
        }
    }, 100);
}

