// ==========================================
// MÓDULO 8: ALTERNÂNCIA DE VISUALIZAÇÃO
// ==========================================
function iniciarToggleVisualizacao() {
    let botaoVisualizacao = document.getElementById("btnToggleView");
    let containerNacao = document.querySelector(".nation-content");

    if (botaoVisualizacao && containerNacao) {
        botaoVisualizacao.addEventListener("click", () => {
            containerNacao.classList.toggle("list-view");
            if (containerNacao.classList.contains("list-view")) {
                botaoVisualizacao.innerHTML = "&#9638; MODO CAIXAS";
            } else {
                botaoVisualizacao.innerHTML = "&#9776; MODO LISTA";
            }
        });
    }
}

// ==========================================
// MÓDULO 9: GESTÃO DE CONFIGURAÇÕES LOCAIS
// ==========================================
function iniciarConfig() {
    let modalConfig = document.getElementById("configModal");
    let btnAbreConfig = document.getElementById("btnOpenConfig");
    let btnFechaConfig = document.getElementById("closeConfigModal");
    let togglePerformance = document.getElementById("togglePerf");
    let seletorTema = document.getElementById("themeSelect");
    let seletorIdioma = document.getElementById("langSelect");
    let botaoPurgar = document.getElementById("btnPurge");

    if (!modalConfig || !btnAbreConfig) return;

    btnAbreConfig.addEventListener("click", evento => {
        evento.preventDefault();
        modalConfig.classList.add("ativo");
    });

    btnFechaConfig.addEventListener("click", () => modalConfig.classList.remove("ativo"));

    if (localStorage.getItem("lowPerf") === "true") {
        togglePerformance.checked = true;
        document.body.classList.add("low-perf");
    }
    togglePerformance.addEventListener("change", evento => {
        if (evento.target.checked) {
            localStorage.setItem("lowPerf", "true");
            document.body.classList.add("low-perf");
        } else {
            localStorage.setItem("lowPerf", "false");
            document.body.classList.remove("low-perf");
        }
    });

    let temaGuardado = localStorage.getItem("siteTheme") || "dark";
    seletorTema.value = temaGuardado;
    if (temaGuardado === "desert") document.body.classList.add("theme-desert");
    if (temaGuardado === "night") document.body.classList.add("theme-night");

    seletorTema.addEventListener("change", evento => {
        document.body.classList.remove("theme-desert", "theme-night");
        if (evento.target.value === "desert") document.body.classList.add("theme-desert");
        if (evento.target.value === "night") document.body.classList.add("theme-night");
        localStorage.setItem("siteTheme", evento.target.value);
    });

    let idiomaGuardado = localStorage.getItem("siteLang") || "pt";
    seletorIdioma.value = idiomaGuardado;
    seletorIdioma.addEventListener("change", evento => {
        localStorage.setItem("siteLang", evento.target.value);
        let banner = document.getElementById("customBanner");
        if (banner) {
            document.getElementById("customBannerText").textContent = "Idioma salvo. Atualize a página para aplicar a tradução.";
            document.getElementById("bannerIcon").innerHTML = "language";
            banner.classList.add("show");
            setTimeout(() => banner.classList.remove("show"), 4000);
        }
    });

    botaoPurgar.addEventListener("click", () => {
        localStorage.clear();
        location.reload();
    });
}

// ==========================================
// FUNÇÃO MESTRA: INICIALIZADOR GLOBAL (BOOTSTRAP)
// ==========================================
function injetarMenu(prefixoUrl) {
    document.addEventListener("DOMContentLoaded", () => {
        injetarInterface(prefixoUrl);
        iniciarLogin(prefixoUrl);
        iniciarSeletorNacao(prefixoUrl);
        iniciarRegistro(prefixoUrl);
        iniciarConfig();
        iniciarBusca(prefixoUrl);
        iniciarScrollSuave(prefixoUrl);
        iniciarRelogio();
        iniciarToggleVisualizacao();
        iniciarRecuperacaoSenha(prefixoUrl);
        iniciarTropas(prefixoUrl);

        document.addEventListener("click", evento => {
            let btnToggle = document.getElementById("navToggleBtn");
            let barraMenu = document.querySelector(".top-navbar");
            if (btnToggle && barraMenu) {
                if (btnToggle.contains(evento.target)) {
                    barraMenu.classList.toggle("expanded");
                } else if (!barraMenu.contains(evento.target) && barraMenu.classList.contains("expanded")) {
                    barraMenu.classList.remove("expanded");
                }
            }
        });
    });
}

// ==========================================
// MÓDULO AUXILIAR: CARROSSEL MANUAL DAS FICHAS
// ==========================================
document.addEventListener("DOMContentLoaded", () => {
    let trilhaImagens = document.getElementById("tank-track");
    let legendaImagens = document.getElementById("tank-caption");
    let botaoProximo = document.getElementById("btnNext");
    let botaoAnterior = document.getElementById("btnPrev");

    if (trilhaImagens && legendaImagens && botaoProximo && botaoAnterior) {
        let slides = Array.from(trilhaImagens.children);
        let slideAtual = 0;

        function renderizarSlide() {
            let deslocamento = 100 * slideAtual;
            trilhaImagens.style.transform = `translateX(-${deslocamento}%)`;
            if (slides[slideAtual] && slides[slideAtual].alt) {
                legendaImagens.textContent = slides[slideAtual].alt;
            }
        }

        renderizarSlide();

        botaoProximo.addEventListener("click", () => {
            slideAtual = slideAtual < slides.length - 1 ? slideAtual + 1 : 0;
            renderizarSlide();
        });

        botaoAnterior.addEventListener("click", () => {
            slideAtual = slideAtual > 0 ? slideAtual - 1 : slides.length - 1;
            renderizarSlide();
        });
    }
});